{
  "name": "Anzil Himalayan Shilajit",
  "description": "Premium, SEO-friendly landing page for Anzil Himalayan Shilajit Resin, featuring an AI-powered wellness assistant.",
  "requestFramePermissions": [
    "microphone"
  ]
}

export interface Feature {
  id: string;
  title: string;
  description: string;
  icon: string;
}

export interface FAQItem {
  question: string;
  answer: string;
}

export interface Testimonial {
