export default Navbar;

import React, { useState, useRef, useEffect } from 'react';
import { getWellnessResponse } from '../services/gemini';
import { ChatMessage } from '../types';

const AIAssistant: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: 'Hello! I am your Anzil Wellness Expert. Ask me anything about Himalayan Shilajit!' }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsLoading(true);

    const response = await getWellnessResponse(userMessage);

    setIsLoading(false);
    setMessages(prev => [...prev, { role: 'model', text: response }]);
  };

  return (
    <section className="py-20 bg-stone-100" id="ai-assistant">
      <div className="container mx-auto px-6">
        <div className="max-w-4xl mx-auto flex flex-col md:flex-row gap-12 items-center">
          <div className="md:w-1/2">
            <h2 className="text-4xl font-bold mb-6 text-shilajit-brown">Ask Our AI Wellness Expert</h2>
            <p className="text-stone-600 mb-8 leading-relaxed">
              Confused about dosage? Wondering if Shilajit is right for you? Our AI expert is trained on the latest research and specific benefits of Anzil's premium resin.
            </p>
            <div className="space-y-4">
              <div className="flex items-center space-x-3 text-sm text-stone-500 font-medium uppercase tracking-wider">
                <span className="w-2 h-2 rounded-full bg-green-500"></span>
                <span>Instant Expert Guidance</span>
              </div>
              <div className="flex items-center space-x-3 text-sm text-stone-500 font-medium uppercase tracking-wider">
                <span className="w-2 h-2 rounded-full bg-green-500"></span>
                <span>Personalized Usage Advice</span>
              </div>
            </div>
          </div>

          <div className="md:w-1/2 w-full">
            <div className="bg-white rounded-2xl shadow-2xl overflow-hidden border border-stone-200 h-[500px] flex flex-col">
              <div className="bg-shilajit-brown p-4 flex items-center space-x-3">
                <div className="w-10 h-10 rounded-full bg-gold-accent flex items-center justify-center text-white font-bold">A</div>
                <div>
                  <h4 className="text-white font-semibold">Anzil Wellness AI</h4>
                  <p className="text-white/60 text-xs">Always Active</p>
                </div>
              </div>

              <div className="flex-1 overflow-y-auto p-6 space-y-4 scroll-smooth" ref={scrollRef}>
                {messages.map((msg, idx) => (
                  <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                    <div className={`max-w-[85%] p-4 rounded-2xl text-sm leading-relaxed ${
                      msg.role === 'user' 
                        ? 'bg-gold-accent text-white rounded-tr-none' 
                        : 'bg-stone-100 text-stone-800 rounded-tl-none border border-stone-200'
                    }`}>
                      {msg.text}
                    </div>
                  </div>
                ))}
                {isLoading && (
                  <div className="flex justify-start">
                    <div className="bg-stone-100 p-4 rounded-2xl rounded-tl-none border border-stone-200 space-x-1 flex">
                      <div className="w-1.5 h-1.5 bg-stone-400 rounded-full animate-bounce"></div>
                      <div className="w-1.5 h-1.5 bg-stone-400 rounded-full animate-bounce [animation-delay:-.3s]"></div>
                      <div className="w-1.5 h-1.5 bg-stone-400 rounded-full animate-bounce [animation-delay:-.5s]"></div>
                    </div>
                  </div>
                )}
              </div>

              <form onSubmit={handleSubmit} className="p-4 bg-stone-50 border-t border-stone-200 flex space-x-2">
                <input 
                  type="text" 
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  placeholder="Ask a question..."
                  className="flex-1 bg-white border border-stone-200 rounded-full px-5 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-gold-accent"
                />
                <button 
                  type="submit"
                  disabled={isLoading}
                  className="bg-gold-accent text-white p-3 rounded-full hover:bg-opacity-90 transition-all disabled:opacity-50"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 rotate-90" viewBox="0 0 20 20" fill="currentColor">
                    <path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" />
                  </svg>
                </button>
              </form>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default AIAssistant;

