import React, { useState, useEffect } from 'react';

interface NavbarProps {
  onNavigate: (page: 'home' | 'certificates') => void;
  currentPage: string;
}

const Navbar: React.FC<NavbarProps> = ({ onNavigate, currentPage }) => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const isHome = currentPage === 'home';
  const navColorClass = (isScrolled || !isHome) ? 'text-shilajit-brown' : 'text-white';
  const bgColorClass = (isScrolled || !isHome) ? 'bg-white shadow-md py-3' : 'bg-transparent py-6';

  const handleHomeAnchor = (e: React.MouseEvent, anchor: string) => {
    if (!isHome) {
      e.preventDefault();
      onNavigate('home');
      // Delay to allow page swap before scrolling
      setTimeout(() => {
        window.location.hash = anchor;
      }, 100);
    }
    setIsMobileMenuOpen(false);
  };

  return (
    <>
      <nav className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${bgColorClass}`}>
        <div className="container mx-auto px-6 flex justify-between items-center">
          <div 
            className="flex items-center space-x-2 cursor-pointer z-50"
            onClick={() => { onNavigate('home'); setIsMobileMenuOpen(false); }}
          >
            <span className={`text-2xl font-bold tracking-tighter serif ${isMobileMenuOpen ? 'text-white' : navColorClass}`}>
              ANZIL
            </span>
          </div>

          {/* Desktop Menu */}
          <div className="hidden md:flex space-x-8 items-center font-medium text-sm uppercase tracking-widest">
            <a 
              href="#benefits" 
              onClick={(e) => handleHomeAnchor(e, 'benefits')}
              className={`${navColorClass} hover:text-gold-accent transition-colors`}
            >
              Benefits
            </a>
            <a 
              href="#faq" 
              onClick={(e) => handleHomeAnchor(e, 'faq')}
              className={`${navColorClass} hover:text-gold-accent transition-colors`}
            >
              FAQ
            </a>
            <button 
              onClick={() => onNavigate('certificates')}
              className={`${navColorClass} hover:text-gold-accent transition-colors ${currentPage === 'certificates' ? 'text-gold-accent border-b-2 border-gold-accent' : ''}`}
            >
              Certificates
            </button>
            <a href="#shop" onClick={(e) => handleHomeAnchor(e, 'shop')} className="bg-gold-accent text-white px-6 py-2 rounded-full hover:bg-opacity-90 transition-all transform hover:scale-105">Shop Now</a>
          </div>

          {/* Mobile Toggle */}
          <button 
            className={`md:hidden z-50 p-2 transition-colors ${isMobileMenuOpen ? 'text-white' : 'text-gold-accent'}`}
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            aria-label="Toggle Menu"
          >
            {isMobileMenuOpen ? (
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            ) : (
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" />
              </svg>
            )}
          </button>
        </div>
