const getSystemInstruction = (lang: 'en' | 'id') => `
You are the AI Wellness Expert for "Anzil Himalayan Shilajit Resin".
Your goal is to educate users about the benefits, usage, and purity of Anzil Shilajit.

CURRENT LANGUAGE: ${lang === 'id' ? 'Bahasa Indonesia' : 'English'}.
YOU MUST RESPOND ONLY IN ${lang === 'id' ? 'Bahasa Indonesia' : 'English'}.

Key Product Facts:
- Sourced from above 16,000 ft in the Himalayan mountains.
- 100% Pure resin form (the most potent version).
- Contains over 84 trace minerals and high levels of Fulvic Acid.
- Lab tested for purity and heavy metals.
- Benefits: Natural energy, cognitive support, immunity booster, anti-aging, and hormonal balance.
- Usage: Pea-sized amount (approx. 250mg-500mg) dissolved in warm water, milk, or green tea. Best taken on an empty stomach in the morning.

Guidelines:
1. Be professional, informative, and encouraging.
2. If asked about medical conditions, always advise consulting a doctor.
3. Keep responses concise and focused on wellness.
4. Mention the brand "Anzil" naturally in conversation.
`;

export const getWellnessResponse = async (userMessage: string, lang: 'en' | 'id' = 'en') => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: userMessage,
      config: {
        systemInstruction: getSystemInstruction(lang),
        temperature: 0.7,
        topP: 0.8,
        topK: 40,
      },
    });

    return response.text || (lang === 'id' ? "Saya di sini untuk membantu pertanyaan Shilajit Anda." : "I'm here to help with your Shilajit questions.");
  } catch (error) {
    console.error("Gemini API Error:", error);
    return lang === 'id' ? "Maaf, terjadi kesalahan teknis." : "I'm having a bit of trouble connecting.";
  }
};

import React, { createContext, useContext, useState, ReactNode } from 'react';
import { translations } from '../translations';

type Language = 'en' | 'id';

interface LanguageContextType {
  language: Language;
  setLanguage: (lang: Language) => void;
  t: any;
}

const LanguageContext = createContext<LanguageContextType | undefined>(undefined);

export const LanguageProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [language, setLanguage] = useState<Language>('en');

  const t = translations[language];

  return (
    <LanguageContext.Provider value={{ language, setLanguage, t }}>
      {children}
    </LanguageContext.Provider>
  );
};

export const useLanguage = () => {
  const context = useContext(LanguageContext);
  if (context === undefined) {
    throw new Error('useLanguage must be used within a LanguageProvider');
  }
  return context;
};

