import React, { useState, useEffect } from 'react';
import { useLanguage } from '../context/LanguageContext';

interface NavbarProps {
  onNavigate: (page: 'home' | 'certificates' | 'blog') => void;
  currentPage: string;
}

const Navbar: React.FC<NavbarProps> = ({ onNavigate, currentPage }) => {
  const { language, setLanguage, t } = useLanguage();
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const isHome = currentPage === 'home';
  const navColorClass = (isScrolled || !isHome) ? 'text-shilajit-brown' : 'text-white';
  const bgColorClass = (isScrolled || !isHome) ? 'bg-white shadow-md py-3' : 'bg-transparent py-6';

  const handleHomeAnchor = (e: React.MouseEvent, anchor: string) => {
    if (!isHome) {
      e.preventDefault();
      onNavigate('home');
      setTimeout(() => {
        window.location.hash = anchor;
      }, 100);
    }
    setIsMobileMenuOpen(false);
  };

  return (
    <>
      <nav className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${bgColorClass}`}>
        <div className="container mx-auto px-6 flex justify-between items-center">
          <div 
            className="flex items-center space-x-2 cursor-pointer z-50"
            onClick={() => { onNavigate('home'); setIsMobileMenuOpen(false); }}
          >
            <span className={`text-2xl font-bold tracking-tighter serif ${isMobileMenuOpen ? 'text-white' : navColorClass}`}>
              ANZIL
            </span>
          </div>

          <div className="hidden md:flex space-x-8 items-center font-medium text-sm uppercase tracking-widest">
            <a 
              href="#benefits" 
              onClick={(e) => handleHomeAnchor(e, 'benefits')}
              className={`${navColorClass} hover:text-gold-accent transition-colors`}
            >
              {t.nav.benefits}
            </a>
            <button 
              onClick={() => onNavigate('blog')}
              className={`${navColorClass} hover:text-gold-accent transition-colors ${currentPage === 'blog' ? 'text-gold-accent border-b-2 border-gold-accent' : ''}`}
            >
              {t.nav.blog}
            </button>
            <button 
              onClick={() => onNavigate('certificates')}
              className={`${navColorClass} hover:text-gold-accent transition-colors ${currentPage === 'certificates' ? 'text-gold-accent border-b-2 border-gold-accent' : ''}`}
            >
              {t.nav.certificates}
            </button>

            <div className={`flex items-center space-x-2 border-l border-stone-200 pl-6 ml-2 ${navColorClass}`}>
              <button onClick={() => setLanguage('en')} className={`transition-colors hover:text-gold-accent ${language === 'en' ? 'font-bold underline underline-offset-4' : 'opacity-50'}`}>EN</button>
              <span>|</span>
              <button onClick={() => setLanguage('id')} className={`transition-colors hover:text-gold-accent ${language === 'id' ? 'font-bold underline underline-offset-4' : 'opacity-50'}`}>ID</button>
            </div>

            <a href="#shop" onClick={(e) => handleHomeAnchor(e, 'shop')} className="bg-gold-accent text-white px-6 py-2 rounded-full hover:bg-opacity-90 transition-all transform hover:scale-105">
              {t.nav.shop}
            </a>
          </div>

          <button className={`md:hidden z-50 p-2 transition-colors ${isMobileMenuOpen ? 'text-white' : 'text-gold-accent'}`} onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>
            {isMobileMenuOpen ? (
              <svg className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
            ) : (
              <svg className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" /></svg>
            )}
          </button>
        </div>
      </nav>

      <div className={`fixed inset-0 z-[45] bg-shilajit-brown transition-transform duration-500 md:hidden ${isMobileMenuOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="flex flex-col items-center justify-center h-full space-y-8 text-center px-6">
          <button onClick={() => { onNavigate('home'); setIsMobileMenuOpen(false); }} className="text-3xl font-bold text-white serif">{t.nav.home}</button>
          <button onClick={() => { onNavigate('blog'); setIsMobileMenuOpen(false); }} className={`text-xl font-medium uppercase tracking-widest ${currentPage === 'blog' ? 'text-gold-accent' : 'text-white/70'}`}>{t.nav.blog}</button>
          <button onClick={() => { onNavigate('certificates'); setIsMobileMenuOpen(false); }} className={`text-xl font-medium uppercase tracking-widest ${currentPage === 'certificates' ? 'text-gold-accent' : 'text-white/70'}`}>{t.nav.certificates}</button>

          <div className="flex space-x-6 text-xl font-bold text-white">
            <button onClick={() => { setLanguage('en'); setIsMobileMenuOpen(false); }} className={language === 'en' ? 'text-gold-accent' : ''}>EN</button>
            <span className="opacity-30">|</span>
            <button onClick={() => { setLanguage('id'); setIsMobileMenuOpen(false); }} className={language === 'id' ? 'text-gold-accent' : ''}>ID</button>
          </div>

          <a href="#shop" onClick={(e) => handleHomeAnchor(e, 'shop')} className="bg-gold-accent text-white w-full py-4 rounded-full text-xl font-bold">{t.nav.shop}</a>
        </div>
      </div>
    </>
  );
};

export default Navbar;

import React, { useState, useEffect } from 'react';
import { LanguageProvider, useLanguage } from './context/LanguageContext';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import Benefits from './components/Benefits';
import AIAssistant from './components/AIAssistant';
import ProductFeature from './components/ProductFeature';
import Footer from './components/Footer';
import CertificatesPage from './components/CertificatesPage';
import BlogPage from './components/BlogPage';
import BlogPostPage from './components/BlogPostPage';
import { blogPosts } from './data/blog-posts';

type Page = 'home' | 'certificates' | 'blog' | 'blog-post';

const AppContent: React.FC = () => {
  const { t } = useLanguage();
  const [currentPage, setCurrentPage] = useState<Page>('home');
  const [selectedPostId, setSelectedPostId] = useState<string | null>(null);

  useEffect(() => {
    window.scrollTo(0, 0);
  }, [currentPage, selectedPostId]);

  const navigateTo = (page: Page) => {
    setCurrentPage(page);
    if (page !== 'blog-post') {
      setSelectedPostId(null);
    }
  };

  const handlePostSelect = (postId: string) => {
    setSelectedPostId(postId);
    setCurrentPage('blog-post');
  };

  const selectedPost = selectedPostId ? blogPosts.find(p => p.id === selectedPostId) : null;

  return (
    <div className="min-h-screen">
      <Navbar onNavigate={navigateTo} currentPage={currentPage} />

      {currentPage === 'home' && (
        <main>
          <Hero />

          <section className="py-24 bg-white">
            <div className="container mx-auto px-6">
              <div className="flex flex-col md:flex-row items-center gap-16">
                <div className="md:w-1/2">
                  <div className="relative group">
                    <img 
                      src="https://images.unsplash.com/photo-1611080626919-7cf5a9dbab5b?auto=format&fit=crop&q=80&w=1000" 
                      alt="Artisanal Himalayan Sourcing" 
                      className="rounded-[3rem] shadow-2xl transition-transform duration-700 group-hover:scale-[1.02]"
                    />
                    <div className="absolute -bottom-6 -right-6 bg-gold-accent p-8 rounded-3xl shadow-xl hidden lg:block">
                      <p className="text-white font-bold text-xl serif">"{t.intro.quote}"</p>
                    </div>
                  </div>
                </div>
                <div className="md:w-1/2">
                  <span className="text-gold-accent font-bold uppercase tracking-widest text-xs mb-4 block">{t.intro.tag}</span>
                  <h2 className="text-4xl md:text-5xl font-bold text-shilajit-brown mb-6 serif">{t.intro.title}</h2>
                  <p className="text-stone-600 text-lg leading-relaxed mb-8">
                    {t.intro.desc}
                  </p>
                  <div className="grid grid-cols-2 gap-8 border-t border-stone-100 pt-8">
                    <div>
                      <h4 className="text-2xl font-bold text-shilajit-brown mb-1 serif">16,000 ft</h4>
                      <p className="text-stone-400 text-[10px] font-bold uppercase tracking-widest">{t.intro.stats.altitude}</p>
                    </div>
                    <div>
                      <h4 className="text-2xl font-bold text-shilajit-brown mb-1 serif">100% Raw</h4>
                      <p className="text-stone-400 text-[10px] font-bold uppercase tracking-widest">{t.intro.stats.potency}</p>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </section>

          <Benefits />
          <AIAssistant />
          <ProductFeature />

          <section id="faq" className="py-24 bg-white">
            <div className="container mx-auto px-6">
              <h2 className="text-4xl font-bold text-center text-shilajit-brown mb-16 serif">{t.faq.title}</h2>
              <div className="max-w-3xl mx-auto space-y-4">
                {t.faq.items.map((faq: any, i: number) => (
                  <details key={i} className="group p-6 rounded-2xl border border-stone-100 hover:border-stone-200 transition-all">
                    <summary className="list-none flex justify-between items-center cursor-pointer font-bold text-lg text-shilajit-brown serif">
                      {faq.q}
                      <span className="text-gold-accent group-open:rotate-45 transition-transform duration-300 text-2xl">+</span>
                    </summary>
                    <p className="mt-4 text-stone-500 leading-relaxed text-sm">{faq.a}</p>
                  </details>
                ))}
              </div>
            </div>
          </section>
        </main>
      )}

      {currentPage === 'certificates' && (
        <CertificatesPage onBack={() => navigateTo('home')} />
      )}

      {currentPage === 'blog' && (
        <BlogPage onPostSelect={handlePostSelect} />
      )}

      {currentPage === 'blog-post' && selectedPost && (
        <BlogPostPage post={selectedPost} onBack={() => navigateTo('blog')} />
      )}

      <Footer />

      <div className="md:hidden fixed bottom-6 left-6 right-6 z-50">
        <a href="#shop" className="bg-shilajit-brown text-white w-full py-4 rounded-full text-center font-bold shadow-2xl block border border-white/10 backdrop-blur-sm">
          {t.product.name}
        </a>
      </div>
    </div>
  );
};

const App: React.FC = () => (
  <LanguageProvider>
    <AppContent />
  </LanguageProvider>
);

export default App;

