3. Keep responses concise.
`;

export const getWellnessResponse = async (userMessage: string, lang: 'en' | 'id' = 'en') => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: userMessage,
      config: {
        systemInstruction: getSystemInstruction(lang),
        temperature: 0.7,
      },
    });

    return response.text || (lang === 'id' ? "Halo! Ada yang bisa saya bantu?" : "Hello! How can I help you?");
  } catch (error) {
    console.error("Gemini API Error:", error);
    return lang === 'id' ? "Maaf, terjadi kendala koneksi." : "I'm having trouble connecting right now.";
  }
};

