type Page = 'home' | 'certificates' | 'blog' | 'blog-post' | 'admin';

const AppContent: React.FC = () => {
  const { language, t } = useLanguage();
  const [currentPage, setCurrentPage] = useState<Page>('home');
  const [selectedPostId, setSelectedPostId] = useState<string | null>(null);
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);

  const [blogPosts, setBlogPosts] = useState(() => {
    const saved = localStorage.getItem('anzil_blog_posts');
    return saved ? JSON.parse(saved) : initialBlogPosts;
  });

  const [siteContent, setSiteContent] = useState<EditableContent>(() => {
    const saved = localStorage.getItem('anzil_site_content');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        // Deep merge logic with fallback to DEFAULT_CONTENT for new fields
        return {
          ...DEFAULT_CONTENT,
          ...parsed,
          hero: { ...DEFAULT_CONTENT.hero, ...parsed.hero },
          intro: { ...DEFAULT_CONTENT.intro, ...parsed.intro },
          product: { ...DEFAULT_CONTENT.product, ...parsed.product },
          benefits: { ...DEFAULT_CONTENT.benefits, ...parsed.benefits },
          faq: { ...DEFAULT_CONTENT.faq, ...parsed.faq },
          certs: { ...DEFAULT_CONTENT.certs, ...parsed.certs },
          ai: { ...DEFAULT_CONTENT.ai, ...parsed.ai },
        };
      } catch (e) {
        console.error("Failed to parse site content", e);
        return DEFAULT_CONTENT;
      }
    }
    return DEFAULT_CONTENT;
  });

  useEffect(() => {
    localStorage.setItem('anzil_blog_posts', JSON.stringify(blogPosts));
  }, [blogPosts]);

  useEffect(() => {
    localStorage.setItem('anzil_site_content', JSON.stringify(siteContent));
  }, [siteContent]);

  useEffect(() => {
    window.scrollTo(0, 0);
  }, [currentPage, selectedPostId]);

  const navigateTo = (page: Page) => {
    setCurrentPage(page);
    if (page !== 'blog-post') setSelectedPostId(null);
  };

  const selectedPost = selectedPostId ? blogPosts.find((p: any) => p.id === selectedPostId) : null;

  if (currentPage === 'admin') {
    return (
      <AdminPanel 
        onExit={() => navigateTo('home')} 
        blogPosts={blogPosts} 
        setBlogPosts={setBlogPosts}
        siteContent={siteContent}
        setSiteContent={setSiteContent}
        isAuthenticated={isAdminAuthenticated}
        setAuthenticated={setIsAdminAuthenticated}
      />
    );
  }

  return (
    <div className="min-h-screen">
      <Navbar onNavigate={navigateTo} currentPage={currentPage} />

      {currentPage === 'home' && (
        <main>
          <Hero content={siteContent.hero} />

          <section className="py-24 bg-white">
            <div className="container mx-auto px-6">
              <div className="flex flex-col md:flex-row items-center gap-16">
                <div className="md:w-1/2">
                  <div className="relative group">
                    <img 
                      src={siteContent.intro.image} 
                      alt="Artisanal Himalayan Sourcing" 
                      className="rounded-[3rem] shadow-2xl transition-transform duration-700 group-hover:scale-[1.02] w-full aspect-square object-cover"
                    />
                    <div className="absolute -bottom-6 -right-6 bg-gold-accent p-8 rounded-3xl shadow-xl hidden lg:block max-w-xs">
                      <p className="text-white font-bold text-xl serif">"{language === 'en' ? siteContent.intro.quoteEn : siteContent.intro.quoteId}"</p>
                    </div>
                  </div>
                </div>
                <div className="md:w-1/2">
                  <span className="text-gold-accent font-bold uppercase tracking-widest text-xs mb-4 block">{t.intro.tag}</span>
                  <h2 className="text-4xl md:text-5xl font-bold text-shilajit-brown mb-6 serif">
                    {language === 'en' ? siteContent.intro.titleEn : siteContent.intro.titleId}
                  </h2>
                  <p className="text-stone-600 text-lg leading-relaxed mb-8">
                    {language === 'en' ? siteContent.intro.descEn : siteContent.intro.descId}
                  </p>
                  <div className="grid grid-cols-2 gap-8 border-t border-stone-100 pt-8">
                    <div>
                      <h4 className="text-2xl font-bold text-shilajit-brown mb-1 serif">16,000 ft</h4>
                      <p className="text-stone-400 text-[10px] font-bold uppercase tracking-widest">{t.intro.stats.altitude}</p>
                    </div>
                    <div>
                      <h4 className="text-2xl font-bold text-shilajit-brown mb-1 serif">100% Raw</h4>
                      <p className="text-stone-400 text-[10px] font-bold uppercase tracking-widest">{t.intro.stats.potency}</p>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </section>

          <Benefits content={siteContent.benefits} />
          <ProductFeature content={siteContent.product} />

          <AIAssistant content={siteContent.ai} />

          <section id="faq" className="py-24 bg-white">
            <div className="container mx-auto px-6">
              <h2 className="text-4xl font-bold text-center text-shilajit-brown mb-16 serif">
                {language === 'en' ? siteContent.faq.titleEn : siteContent.faq.titleId}
              </h2>
              <div className="max-w-3xl mx-auto space-y-4">
                {siteContent.faq.items.map((faq, i) => (
                  <details key={i} className="group p-6 rounded-2xl border border-stone-100 hover:border-stone-200 transition-all">
                    <summary className="list-none flex justify-between items-center cursor-pointer font-bold text-lg text-shilajit-brown serif">
                      {language === 'en' ? faq.qEn : faq.qId}
                      <span className="text-gold-accent group-open:rotate-45 transition-transform duration-300 text-2xl">+</span>
                    </summary>
                    <p className="mt-4 text-stone-500 leading-relaxed text-sm">
                      {language === 'en' ? faq.aEn : faq.aId}
                    </p>
                  </details>
                ))}
              </div>
            </div>
          </section>
        </main>
      )}

      {currentPage === 'certificates' && (
        <CertificatesPage onBack={() => navigateTo('home')} content={siteContent.certs} />
      )}

      {currentPage === 'blog' && (
        <BlogPage onPostSelect={(id) => { setSelectedPostId(id); setCurrentPage('blog-post'); }} posts={blogPosts} />
      )}

      {currentPage === 'blog-post' && selectedPost && (
        <BlogPostPage post={selectedPost} onBack={() => navigateTo('blog')} />
      )}

      <Footer content={siteContent.product} onAdminClick={() => navigateTo('admin')} />
    </div>
  );
};

const App: React.FC = () => (
  <LanguageProvider>
    <AppContent />
  </LanguageProvider>
);

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { getWellnessResponse } from '../services/gemini';
import { useLanguage } from '../context/LanguageContext';
import { ChatMessage } from '../types';

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }
  interface Window {
    aistudio?: AIStudio;
  }
}

interface AIAssistantProps {
  content: {
    titleEn: string;
    titleId: string;
    descEn: string;
    descId: string;
    initialEn: string;
    initialId: string;
    placeholderEn: string;
    placeholderId: string;
    expertNameEn: string;
    expertNameId: string;
    statusEn: string;
    statusId: string;
    featuresEn: string[];
    featuresId: string[];
  };
}

const AIAssistant: React.FC<AIAssistantProps> = ({ content }) => {
  const { language } = useLanguage();

  const title = language === 'en' ? content.titleEn : content.titleId;
  const desc = language === 'en' ? content.descEn : content.descId;
  const initialMessage = language === 'en' ? content.initialEn : content.initialId;
  const placeholder = language === 'en' ? content.placeholderEn : content.placeholderId;
  const expertName = language === 'en' ? content.expertNameEn : content.expertNameId;
  const status = language === 'en' ? content.statusEn : content.statusId;
  const features = language === 'en' ? content.featuresEn : content.featuresId;

  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: initialMessage }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showKeyButton, setShowKeyButton] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const checkInitialKey = async () => {
      if (window.aistudio && typeof window.aistudio.hasSelectedApiKey === 'function') {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        if (!hasKey) {
          setShowKeyButton(true);
        }
      }
    };
    checkInitialKey();
  }, []);

  useEffect(() => {
    // Reset messages when language changes to the new localized initial message
    setMessages([{ role: 'model', text: initialMessage }]);
  }, [language, initialMessage]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleOpenKeyDialog = async () => {
    if (window.aistudio && typeof window.aistudio.openSelectKey === 'function') {
      await window.aistudio.openSelectKey();
      setShowKeyButton(false);
      setMessages(prev => [...prev, { 
        role: 'model', 
        text: language === 'id' ? "Kunci API telah dipilih. Silakan coba kirim pesan Anda lagi." : "API key selected. Please try sending your message again." 
      }]);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsLoading(true);

    const result = await getWellnessResponse(userMessage, language);

    setIsLoading(false);
    setMessages(prev => [...prev, { role: 'model', text: result.text }]);

    if (result.error === 'AUTH_REQUIRED') {
      setShowKeyButton(true);
    }
  };

  return (
    <section className="py-20 bg-stone-100" id="ai-assistant">
      <div className="container mx-auto px-6">
        <div className="max-w-4xl mx-auto flex flex-col md:flex-row gap-12 items-center">
          <div className="md:w-1/2">
            <h2 className="text-4xl font-bold mb-6 text-shilajit-brown serif">{title}</h2>
            <p className="text-stone-600 mb-8 leading-relaxed">
              {desc}
            </p>
            <div className="space-y-4">
              {features.map((feat: string, i: number) => (
                <div key={i} className="flex items-center space-x-3 text-sm text-stone-500 font-medium uppercase tracking-wider">
                  <span className="w-2 h-2 rounded-full bg-green-500"></span>
                  <span>{feat}</span>
                </div>
              ))}
            </div>

            {showKeyButton && (
              <div className="mt-8 p-6 bg-amber-50 border border-amber-200 rounded-2xl shadow-sm">
                <p className="text-amber-800 text-sm mb-4 font-medium">
                  {language === 'id' 
                    ? "Fitur AI memerlukan kunci API berbayar dari proyek GCP Anda."
                    : "AI features require a paid API key from your GCP project."}
                </p>
                <button 
                  onClick={handleOpenKeyDialog}
                  className="bg-gold-accent text-white px-6 py-3 rounded-full text-xs font-bold uppercase tracking-widest hover:bg-opacity-90 transition-all shadow-md mb-4"
                >
                  {language === 'id' ? "Pilih Kunci API" : "Select API Key"}
                </button>
                <p className="text-[10px] text-amber-600 font-bold uppercase tracking-widest">
                  <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noopener noreferrer" className="underline hover:text-shilajit-brown">
                    Documentation: Billing Setup →
                  </a>
                </p>
              </div>
            )}
          </div>

          <div className="md:w-1/2 w-full">
            <div className="bg-white rounded-2xl shadow-2xl overflow-hidden border border-stone-200 h-[500px] flex flex-col">
              <div className="bg-shilajit-brown p-4 flex items-center justify-between">
                <div className="flex items-center space-x-3">
                  <div className="w-10 h-10 rounded-full bg-gold-accent flex items-center justify-center text-white font-bold serif">A</div>
                  <div>
                    <h4 className="text-white font-semibold">{expertName}</h4>
                    <p className="text-white/60 text-xs">{status}</p>
                  </div>
                </div>
                {showKeyButton && (
                  <button 
                    onClick={handleOpenKeyDialog}
                    className="bg-white/10 hover:bg-white/20 text-white text-[10px] font-bold py-1 px-3 rounded-full border border-white/20 transition-all"
                  >
                    Select Key
                  </button>
                )}
              </div>

              <div className="flex-1 overflow-y-auto p-6 space-y-4 scroll-smooth" ref={scrollRef}>
                {messages.map((msg, idx) => (
                  <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                    <div className={`max-w-[85%] p-4 rounded-2xl text-sm leading-relaxed ${
                      msg.role === 'user' 
                        ? 'bg-gold-accent text-white rounded-tr-none' 
                        : 'bg-stone-100 text-stone-800 rounded-tl-none border border-stone-200'
                    }`}>
                      {msg.text}
                      {idx === messages.length - 1 && showKeyButton && (
                        <div className="mt-3 pt-3 border-t border-stone-200">
                          <button 
                            onClick={handleOpenKeyDialog}
                            className="text-gold-accent font-bold text-xs uppercase tracking-widest hover:text-shilajit-brown transition-colors"
                          >
                            Set API Key →
                          </button>
                        </div>
                      )}
                    </div>
                  </div>
                ))}
                {isLoading && (
                  <div className="flex justify-start">
                    <div className="bg-stone-100 p-4 rounded-2xl rounded-tl-none border border-stone-200 space-x-1 flex">
                      <div className="w-1.5 h-1.5 bg-stone-400 rounded-full animate-bounce"></div>
                      <div className="w-1.5 h-1.5 bg-stone-400 rounded-full animate-bounce [animation-delay:-.3s]"></div>
                      <div className="w-1.5 h-1.5 bg-stone-400 rounded-full animate-bounce [animation-delay:-.5s]"></div>
                    </div>
                  </div>
                )}
              </div>

              <form onSubmit={handleSubmit} className="p-4 bg-stone-50 border-t border-stone-200 flex space-x-2">
                <input 
                  type="text" 
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  placeholder={placeholder}
                  className="flex-1 bg-white border border-stone-200 rounded-full px-5 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-gold-accent"
                />
                <button 
                  type="submit"
                  disabled={isLoading}
                  className="bg-gold-accent text-white p-3 rounded-full hover:bg-opacity-90 transition-all disabled:opacity-50"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 rotate-90" viewBox="0 0 20 20" fill="currentColor">
                    <path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" />
                  </svg>
                </button>
              </form>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

