          settings: { ...DEFAULT_CONTENT.settings, ...parsed.settings },
        };
      } catch (e) {
        console.error("Failed to parse site content", e);
        return DEFAULT_CONTENT;
      }
    }
    return DEFAULT_CONTENT;
  });

