                <div key={p.id} className="p-8 bg-white border border-stone-200 rounded-3xl flex justify-between items-center">
                   <p className="font-bold">{p.title.en}</p>
                   <button onClick={() => setBlogPosts(prev => prev.filter(bp => bp.id !== p.id))} className="text-red-400 font-bold uppercase text-[10px]">Delete</button>
                </div>
              ))}
           </div>
        )}
      </main>
    </div>
  );
};

