                       <Field label="Title (EN)" value={item.titleEn} onChange={v => updateNestedContent('certs', i, 'titleEn', v)} />
                       <div className="col-span-2">
                         <Field label="Image URL" value={item.image} onChange={v => updateNestedContent('certs', i, 'image', v)} />
